import{_ as i,l as n,o as e,c as o,v as t,p as s,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"树匹配指令选择","description":"","frontmatter":{"title":"树匹配指令选择","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tree-pattern-isel.md","filePath":"cs/tree-pattern-isel.md","lastUpdated":1789023840000}'),h={name:"cs/tree-pattern-isel.md"};function m(u,a,A,_,f,D){const l=n("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="树匹配指令选择" tabindex="-1">树匹配指令选择 <a class="header-anchor" href="#树匹配指令选择" aria-label="Permalink to &quot;树匹配指令选择&quot;">​</a></h1><div class="epigraph"><p>IR 树用指令模板覆盖：动态规划选代价最小覆盖，每个模板对应一条或一组机器指令。</p><footer>—— 据 Aho, Ganapathi and Tjiang, Code Generation Using Tree Matching and Dynamic Programming；龙书 8.9；Appel 整理</footer></div><p>上一课<a href="/cs/critical-path-scheduling">关键路径</a>假定已有机器指令。主干<a href="/cs/instruction-select">指令选择</a>有直觉。缺口是 <strong>BURS/树匹配 + DP</strong>：像 <code>lea</code> 覆盖 <code>base+idx*scale</code>。本课钉覆盖，不写 TableGen 描述语言——下一课。调度在选择之后（或与 DAG 选择交织，如 LLVM ISel）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>朴素：每个 IR 运算一条 RISC。CISC 与寻址模式要模式匹配。树覆盖：叶到根 DP，代价相加。缺口是<strong>最小代价覆盖</strong>，不是着色。</p><p>DAG 选择：公共子表达式使树变 DAG，覆盖更难（可能复制或用寄存器）。</p><h3 id="覆盖不是语法分析的-earley" tabindex="-1">覆盖不是语法分析的 Earley <a class="header-anchor" href="#覆盖不是语法分析的-earley" aria-label="Permalink to &quot;覆盖不是语法分析的 Earley&quot;">​</a></h3><p>虽然都是动态规划，对象是 IR 树 vs 文法。不要把 burg 当 yacc。</p><p><span class="marginnote">Aho–Ganapathi–Tjiang。TWIG、burg、iburg。LLVM SelectionDAG / GlobalISel。Appel 的 Maximal Munch 是贪心对照。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Maximal Munch：贪心最长匹配，快，非优。DP：每个结点存各非终结符最小代价。生成：按记录的模板吐指令。</p>',11)),(e(),s(c,null,{default:r(()=>[p(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20IR%5B%22IR%20%E6%A0%91%22%5D%20--%3E%20PAT%5B%22%E6%A8%A1%E6%9D%BF%E5%8C%B9%E9%85%8D%22%5D%0A%20%20PAT%20--%3E%20DP%5B%22%E4%BB%A3%E4%BB%B7%20DP%22%5D%0A%20%20DP%20--%3E%20MI%5B%22%E6%9C%BA%E5%99%A8%E6%8C%87%E4%BB%A4%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与 GVN：先编号减树大小。与立即数：选择时要认 ISA 宽度，否则后期再拆。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>非法覆盖用 expand（伪指令 → 真指令）。失败则报后端 bug。不要在选择里做全局调度。</p><p>代价：延迟、长度、是否破坏标志位。fast-math 可允许 <code>fma</code> 模板。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 TableGen 语法。后课默认：树/DAG 覆盖做选择。下一课目标描述：把模板写成可维护的描述。</p><p>也不把指令选择当 SQL 查询选择。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>树匹配 + DP（或贪心 munch）覆盖 IR。</li><li>代价含延迟与编码约束。</li><li>DAG 因共享比树难。</li><li>出处：Aho, Ganapathi and Tjiang；龙书 8.9；Appel Maximal Munch。</li></ul>',9))])}const b=i(h,[["render",m]]);export{T as __pageData,b as default};
